// Parse Config: one shape for every play, read from the Apify webhook payload (body) or the
// task URL's query string. Nothing about a client is in this file; every knob below is a
// payload key, and the defaults are what a play gets when it does not say otherwise.
//
// Required: client (Hub Clients record id), table (Intent table id), campaign (enroll URL),
//           resource (Apify's own object, carries the dataset id).
// Knobs:    country (US), max_headcount (200), event_type (became_hiring),
//           and the decision-maker specs below.
//
// Decision-maker specs. Two per play by default, each a contact-source filter in both
// providers' own vocabulary. Override any list with a comma string, or replace the whole
// set with `specs` as a JSON array of {call, limit, cg:{seniority,department}, sq:{seniority,function}}.
//   tech_limit, tech_cg_seniority, tech_cg_department, tech_sq_seniority, tech_sq_function
//   exec_limit, exec_cg_seniority, exec_cg_department, exec_sq_seniority, exec_sq_function
// ContaGen enums: seniority executive|vp|director|manager|senior_ic; department is one of the
// 15 canonical DiscoLike values (Technology, Research & Development, Executive, Operations...).
// Supersoniq enums: seniority C-Suite|VP|Founder|Owner|President|EVP / SVP|Head|Director;
// function Engineering|R&D|Technology|Executive|Operations|...
//
// Apify's own `eventType` (ACTOR.RUN.SUCCEEDED) is deliberately NOT read: it leaked into
// Event Type on every row until 2026-08-23. Only the play's explicit event_type is honored.
const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
const j=$input.first().json||{};
const q=j.query||{}; const b=j.body||{};
const pick=(k)=>{ const v=(b[k]!==undefined&&b[k]!=='')?b[k]:q[k]; return (v===undefined||v===null)?'':(typeof v==='string'?v.trim():v); };
const num=(v,def)=>{ const n=parseInt(v,10); return Number.isFinite(n)&&n>0?n:def; };
const list=(v,def)=>{ if(Array.isArray(v)) return v.map(x=>String(x).trim()).filter(Boolean); const s=String(v||'').trim(); return s?s.split(',').map(x=>x.trim()).filter(Boolean):def; };

// DiscoLike's `executive` seniority is wide (proven live 2026-08-23: "Founding Growth",
// "Strategic Projects", CMO all carry it), so the exec spec also gates on title terms.
// Knobs per spec: {call}_cg_title, {call}_cg_negate_title (ContaGen only; Supersoniq has no title filter).
const DEFAULT_SPECS=[
  { call:'tech', limit:5,
    cg:{ seniority:['executive','vp','director','manager'], department:['Technology','Research & Development'], title:[], negate_title:[] },
    sq:{ seniority:['C-Suite','VP','Founder','Owner','President','EVP / SVP','Head','Director'], function:['Engineering','R&D','Technology'] } },
  { call:'exec', limit:3,
    cg:{ seniority:['executive'], department:['Executive'], title:['Founder','CEO','CTO','COO','President','Chief Executive','Chief Technology','Chief Operating'], negate_title:['marketing','sales','growth','revenue','people','talent','recruit','brand','community','content'] },
    sq:{ seniority:['C-Suite','Founder','Owner','President'], function:['Executive'] } }
];
const mkCg=(o,d)=>({ seniority:list(o&&o.seniority,d.seniority), department:list(o&&o.department,d.department), title:list(o&&o.title,d.title||[]), negate_title:list(o&&o.negate_title,d.negate_title||[]) });
let specs=null;
const rawSpecs=pick('specs');
if(rawSpecs){ try{ const arr=typeof rawSpecs==='string'?JSON.parse(rawSpecs):rawSpecs; if(Array.isArray(arr)&&arr.length) specs=arr.map(s=>({ call:String(s.call||'custom'), limit:num(s.limit,5), cg:mkCg(s.cg,{seniority:[],department:[],title:[],negate_title:[]}), sq:{ seniority:list(s.sq&&s.sq.seniority,[]), function:list(s.sq&&s.sq.function,[]) } })); }catch(e){} }
if(!specs){
  specs=DEFAULT_SPECS.map(d=>({ call:d.call, limit:num(pick(d.call+'_limit'),d.limit),
    cg:mkCg({ seniority:pick(d.call+'_cg_seniority'), department:pick(d.call+'_cg_department'), title:pick(d.call+'_cg_title'), negate_title:pick(d.call+'_cg_negate_title') }, d.cg),
    sq:{ seniority:list(pick(d.call+'_sq_seniority'),d.sq.seniority), function:list(pick(d.call+'_sq_function'),d.sq.function) } }));
}

const cfg={
  client: String(pick('client')||''),
  table: String(pick('table')||''),
  campaign_url: String(pick('campaign')||''),
  sender: String(pick('sender')||'webhook'),
  max_headcount: num(pick('max_headcount')||pick('maxHeadcount'),200),
  country: String(pick('country')||'US'),
  event_type: String(pick('event_type')||'became_hiring'),
  specs,
  datasetId: (b.resource&&b.resource.defaultDatasetId)||''
};
const missing=[];
if(!cfg.client) missing.push('client');
if(!cfg.table) missing.push('table');
if(!cfg.campaign_url) missing.push('campaign');
else if(!/^https?:\/\//i.test(cfg.campaign_url)) missing.push('campaign (not a URL)');
if(!cfg.datasetId) missing.push('resource.defaultDatasetId (Apify payload)');
cfg.config_ok=(missing.length===0);
cfg.missing=missing;
return [{ json: cfg }];

const r=$input.first().json||{};
const f=r.fields||r;
const name=f['Client']||'';
return [{ json: {
  clientName: name,
  clientRecId: r.id||$('Parse Config').first().json.client||'',
  clientSlug: String(name).toLowerCase().replace(/[^a-z0-9]/g,''),
  slackChannel: f['Slack Channel ID']||'',
  base: f['Clayroots Base ID']||''
}}];

// Filter & Qualify Jobs: 100 scraped job posts in, one row per qualified company out, every
// drop counted by reason. The full job record rides on the company row so the writer can
// stamp it on every contact. _stats on the first row feeds Build Run Log.
//
// Drops, in order: country, staffing (name / poster title / industry), body shop, headcount,
// no domain, duplicate domain, already worked. An unknown headcount passes on purpose: a blank
// LinkedIn count is not a large company, and the downstream contact calls are capped anyway.
const cfg=$('Parse Config').first().json;
let items=$('Get Scraped Jobs').all().map(i=>i.json);
if(items.length===1&&Array.isArray(items[0])) items=items[0];
items=items.filter(j=>j&&(j.companyName||j.companyWebsite||j.title));
const worked=new Set($('Get Worked Domains').all().map(i=>{ const j=i.json||{}; const d=(j.fields&&j.fields.Domain)||j.Domain||''; return String(d).toLowerCase().trim(); }).filter(Boolean));

const badName=['staffing','recruit','headhunt','talent acquisition','executive search','sourcer','consulting','outsourcing'];
const badIndustry=['staffing','recruiting','executive search','venture capital','private equity','venture'];
const has=(s,list)=>{ s=String(s||'').toLowerCase(); return list.some(w=>s.includes(w)); };

// Body-shop test: a real employer names itself in its own post ("Fortreum is seeking...",
// "About IO River"). A staffing firm pastes a bare requirements list for a client it never
// names. Verified on the 2026-08-20 dataset: 6/6. Employer-brand phrases are the second tell.
const LEGAL=/\b(inc|llc|ltd|corp|corporation|co|company|solutions|technologies|technology|group|systems|services|consulting)\b/g;
const BRAND=['equal opportunity','401(k)','401k','we offer','about us','who we are','our team','our mission','our company','join us','benefits'];
function looksLikeBodyShop(j){
  const desc=String(j.descriptionText||'');
  if(!desc) return false;
  const d=desc.toLowerCase();
  const core=String(j.companyName||'').toLowerCase().replace(LEGAL,' ').replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(w=>w.length>=3)[0]||'';
  if(core&&d.includes(core)) return false;
  if(BRAND.some(w=>d.includes(w))) return false;
  return true;
}

const drops={country:0,staffing_name:0,staffing_industry:0,body_shop:0,headcount:0,no_domain:0,duplicate:0,worked:0};
const seen=new Set();
const out=[];
for(const j of items){
  const country=(j.companyAddress&&j.companyAddress.addressCountry)||'';
  if(country&&country!==cfg.country){ drops.country++; continue; }
  if(has(j.companyName,badName)||has(j.jobPosterTitle,badName)){ drops.staffing_name++; continue; }
  if(has(j.industries,badIndustry)){ drops.staffing_industry++; continue; }
  if(looksLikeBodyShop(j)){ drops.body_shop++; continue; }
  const emp=Number(j.companyEmployeesCount||0);
  if(emp>cfg.max_headcount){ drops.headcount++; continue; }
  const domain=String(j.companyWebsite||'').toLowerCase().replace('https://','').replace('http://','').replace('www.','').split('?')[0].split('#')[0].split('/')[0].trim();
  if(!domain){ drops.no_domain++; continue; }
  if(seen.has(domain)){ drops.duplicate++; continue; }
  if(worked.has(domain)){ drops.worked++; continue; }
  seen.add(domain);
  out.push({ json: {
    domain,
    company: j.companyName||'',
    headcount: emp,
    country: country||cfg.country,
    company_linkedin: j.companyLinkedinUrl||'',
    company_website: j.companyWebsite||'',
    job: {
      id: String(j.id||''),
      title: j.title||'',
      link: j.link||'',
      posted_at: j.postedAt||'',
      description: j.descriptionText||'',
      seniority: j.seniorityLevel||'',
      function: j.jobFunction||'',
      employment_type: j.employmentType||'',
      industries: j.industries||'',
      applicants: Number(j.applicantsCount)||null,
      salary: j.salary||'',
      poster_name: j.jobPosterName||'',
      poster_title: j.jobPosterTitle||'',
      poster_linkedin: j.jobPosterProfileUrl||''
    }
  }});
}
const stats={ jobs_in: items.length, qualified: out.length, drops };
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Build Intent Leads: merges the three provider passes into one row per contact, carrying the
// contact, the job that triggered the signal, and the company's DiscoLike firmographics.
//
// Sources, in the builders' order (Contagen -> Supersoniq -> Clayroots):
//   ContaGen   DiscoLike /contacts/discover, Source 1, every contact kept.
//   Supersoniq Source 2, NET-NEW ONLY: a contact whose Contact Key (first+last+domain) already
//              came from ContaGen is skipped, exactly as Format Supersoniq does.
//   BizData    DiscoLike /bizdata, one call per company, firmographics on every row.
//
// Each HTTP node ran with fullResponse + neverError, so every item here is {statusCode, body}
// and a failed call is READ, classified and counted, never silently dropped. Index alignment:
// provider output i belongs to Split Calls row i (one output per input, order preserved);
// BizData output i belongs to Filter & Qualify row i.
//
// Company names go out RAW; the Clean Fields helper (next node) is the one copy of the
// cleaning rules and writes Company / company_clean / public_emails_clean in place.
// Field names are the ClayRoots build vocabulary; Job * fields are this table's own.
const cfg=$('Parse Config').first().json;
const titleCase=(s)=>String(s).replace(/\w\S*/g,t=>t.charAt(0).toUpperCase()+t.slice(1).toLowerCase());
const cleanFirst=(f)=>{if(!f)return'';let n=String(f).split(',')[0].trim().split(/\s+/)[0]||'';n=n.replace(/[^A-Za-z\-']/g,'');return n?n.charAt(0).toUpperCase()+n.slice(1).toLowerCase():'';};
const cleanLast=(f)=>{if(!f)return'';let p=String(f).split(',')[0].trim().split(/\s+/);if(p.length<2)return'';return titleCase(p.slice(1).join(' ').replace(/[^A-Za-z\-'\s]/g,'').trim());};
const join=(a)=>Array.isArray(a)?a.filter(Boolean).join(', '):'';
const kv=(o)=>o&&typeof o==='object'?Object.entries(o).map(([k,v])=>k+':'+(typeof v==='number'?v.toFixed(2):v)).join(', '):'';
const firstPhone=(p)=>Array.isArray(p)&&p.length?String((p[0]&&p[0].phone)||p[0]||''):'';
const linkedinOf=(urls)=>Array.isArray(urls)?(urls.find(u=>/linkedin\.com\/in\//i.test(u))||''):'';
// fullResponse shape is {statusCode, headers, body}; a 204 carries statusCode and NO body key.
const body=(it)=>{ const j=(it&&it.json)||{}; if(j.statusCode!==undefined) return { status:Number(j.statusCode)||0, body:(j.body===undefined?null:j.body) }; return { status: j.error?0:200, body:j }; };
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const why=(b,raw)=>{ const m=b&&typeof b==='object'?(b.detail||b.error||b.message):null; const s=m?String(typeof m==='object'?JSON.stringify(m):m):(typeof raw==='string'?raw:(raw?JSON.stringify(raw):'')); return String(s||'empty body').slice(0,120); };

// Companies, indexed by domain, with the job that put them here.
const companies={};
const companyRows=$('Filter & Qualify Jobs').all().map(i=>i.json).filter(c=>c&&c.domain);
for(const c of companyRows) companies[c.domain]=c;

// BizData, aligned to companyRows by index; body.domain confirms the match when present.
const failed=[];
const biz={};
const bizStats={called:0,matched:0,errors:0};
let bizItems=[]; try{ bizItems=$('DiscoLike BizData').all(); }catch(e){}
bizItems.forEach((it,i)=>{
  const c=companyRows[i]; if(!c) return;
  bizStats.called++;
  const r=body(it); const b=parse(r.body);
  if(r.status>=200&&r.status<300&&b&&typeof b==='object'&&(b.domain||b.name)){ biz[c.domain]=b; bizStats.matched++; return; }
  // 204 No Content and 404 are DiscoLike's "domain unknown": a miss, not an error (proven live 2026-08-23, indie-soft.com).
  if(r.status===204||r.status===404||(b&&b.detail&&/not found/i.test(String(b.detail)))){ bizStats.unknown=(bizStats.unknown||0)+1; return; }
  bizStats.errors++; failed.push({ tier:'BizData', name:c.domain, reason:'HTTP '+r.status+' '+why(b,r.body) });
});

// Split Calls already dropped recruiter platforms on DiscoLike's classification before any
// paid contact call; it reports them on its first row for the log.
let recruiterDrop=[]; try{ recruiterDrop=($('Split Calls').first().json._stats||{}).recruiter_bizdata||[]; }catch(e){}
for(const d of recruiterDrop) delete companies[d];

const calls=$('Split Calls').all().map(i=>i.json).filter(c=>c&&c.domain);
const out=[];
const seenKey=new Set(); const seenLi=new Set();
const nowIso=new Date().toISOString();

function baseRow(c){
  const b=biz[c.domain]||{};
  const j=c.job||{};
  const addr=b.address||{};
  return {
    'Domain': c.domain,
    'Company': String(c.company||b.name||'').trim(),
    'company_clean': String(c.company||b.name||'').trim(),
    'Event Type': cfg.event_type,
    'Target Campaign': cfg.campaign_url,
    'Intent Status': 'NEW',
    'detected_at': nowIso,
    'Job ID': j.id||'', 'Job Title': j.title||'', 'Job Link': j.link||'', 'Job Posted': j.posted_at||null,
    'Job Description': j.description||'', 'Job Seniority': j.seniority||'', 'Job Function': j.function||'',
    'Job Employment Type': j.employment_type||'', 'Job Industries': j.industries||'', 'Job Applicants': j.applicants,
    'Job Salary': j.salary||'', 'Job Poster Name': j.poster_name||'', 'Job Poster Title': j.poster_title||'', 'Job Poster LinkedIn': j.poster_linkedin||'',
    'Description': b.description||'', 'Industry Groups': kv(b.industry_groups), 'Employees': b.employees||'',
    'Revenue Range': b.revenue_range||'', 'Score': b.score!=null?String(b.score):'', 'Keywords': b.keywords?Object.keys(b.keywords).join(', '):'',
    'Company Status': b.status?(b.status.status+(b.status.confidence!=null?' ('+b.status.confidence+')':'')):'',
    'Start Date': b.start_date||'', 'Street': addr.street||'', 'Company City': addr.city||'', 'Company State': addr.state||'',
    'Country': addr.country||c.country||'', 'Zip': addr.zip||'',
    'Phones': join(b.phones), 'Public Emails': join(b.public_emails), 'public_emails_clean': '',
    'Social URLs': join(b.social_urls), 'MX Provider': b.mx_provider||'', 'Redirect Domain': b.redirect_domain||'',
    'Email Pattern': patterns[c.domain]||''
  };
}
const patterns={};
function signal(c){ const j=c.job||{}; return 'Hiring '+(j.title||'an infrastructure role')+(j.posted_at?' (posted '+j.posted_at+')':'')+(c.headcount?' · '+c.headcount+' employees on LinkedIn':'')+'. Job: '+(j.link||''); }
function push(c,p,source,callName){
  const full=String(p.name||'').trim();
  const first=cleanFirst(full), last=cleanLast(full);
  const key=(first.toLowerCase()+last.toLowerCase()+c.domain).trim();
  const li=String(p.linkedin||'').trim();
  if(!key||!first) return 'nokey';
  if(seenKey.has(key)||(li&&seenLi.has(li.toLowerCase()))) return 'dup';
  seenKey.add(key); if(li) seenLi.add(li.toLowerCase());
  out.push({ json: Object.assign(baseRow(c), {
    'Name': full, 'first_name': first, 'last_name': last,
    'LinkedIn URL': li, 'Email': String(p.email||'').trim(),
    'Title': String(p.title||'').trim(), 'Seniority': String(p.seniority||'').trim(), 'Department': String(p.department||'').trim(),
    'Phone': p.phone||'', 'City': p.city||'', 'State': p.state||'',
    'Contact Key': key, 'Contact Source': source,
    'Signal Detail': signal(c)+' · '+source+' '+callName+' · '+(p.title||'')
  })});
  return 'ok';
}

// Source 1: ContaGen.
const cg={called:0,matched:0,contacts:0,kept:0,errors:0};
let cgItems=[]; try{ cgItems=$('ContaGen Contacts').all(); }catch(e){}
cgItems.forEach((it,i)=>{
  const call=calls[i]; if(!call) return; const c=companies[call.domain]; if(!c) return;
  cg.called++;
  const r=body(it); const b=parse(r.body);
  if(!(r.status>=200&&r.status<300)||!b||typeof b!=='object'){ cg.errors++; failed.push({ tier:'ContaGen', name:call.domain+' ('+call.call+')', reason:'HTTP '+r.status+' '+why(b,r.body) }); return; }
  const entry=(b.results&&(b.results[call.domain]||Object.values(b.results)[0]))||null;
  const contacts=(entry&&entry.contacts)||[];
  if(contacts.length) cg.matched++;
  const pattern=entry&&entry.email_pattern?entry.email_pattern+(entry.email_pattern_confidence!=null?' ('+entry.email_pattern_confidence+')':''):'';
  if(pattern&&!patterns[c.domain]) patterns[c.domain]=pattern;
  if(entry&&!biz[c.domain]){ biz[c.domain]={ name:entry.name, employees:entry.employees, revenue_range:entry.revenue_range, industry_groups:entry.industry_groups, address:entry.address }; }
  else if(entry&&biz[c.domain]&&!biz[c.domain].revenue_range&&entry.revenue_range) biz[c.domain].revenue_range=entry.revenue_range;
  for(const p of contacts){
    cg.contacts++;
    const res=push(c,{ name:p.name, title:p.title, seniority:p.seniority, department:p.department, email:p.email, linkedin:linkedinOf(p.social_urls), phone:firstPhone(p.phone), city:'', state:p.state||'', email_pattern:pattern },'ContaGen',call.call);
    if(res==='ok') cg.kept++;
  }
});

// Source 2: Supersoniq, net-new only.
const sq={called:0,matched:0,contacts:0,kept:0,errors:0,credits:0};
let sqItems=[]; try{ sqItems=$('Supersoniq Contacts').all(); }catch(e){}
sqItems.forEach((it,i)=>{
  const call=calls[i]; if(!call) return; const c=companies[call.domain]; if(!c) return;
  sq.called++;
  const r=body(it); const b=parse(r.body);
  if(!(r.status>=200&&r.status<300)||!b||typeof b!=='object'||b.success===false){ sq.errors++; failed.push({ tier:'Supersoniq', name:call.domain+' ('+call.call+')', reason:'HTTP '+r.status+' '+why(b,r.body) }); return; }
  sq.credits+=Number(b.credits_used)||0;
  const comps=Array.isArray(b.results)?b.results:[];
  let any=false;
  for(const comp of comps){
    const contacts=Array.isArray(comp.contacts)?comp.contacts:[comp];
    for(const p of contacts){
      if(!p||!(p.first_name||p.full_name)) continue;
      any=true; sq.contacts++;
      const full=p.full_name||((p.first_name||'')+' '+(p.last_name||'')).trim();
      const res=push(c,{ name:full, title:p.job_title, seniority:p.seniority, department:p.function, email:p.email, linkedin:p.linkedin_url, phone:'', city:p.contact_city||'', state:p.contact_region||'' },'Supersoniq',call.call);
      if(res==='ok') sq.kept++;
    }
  }
  if(any) sq.matched++;
});

const companiesWithContact=new Set(out.map(o=>o.json.Domain)).size;
const stats={ companies:companyRows.length, recruiter_bizdata:recruiterDrop, companies_with_contact:companiesWithContact, contacts:out.length, contagen:cg, supersoniq:sq, bizdata:bizStats, failed };
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Apply DNC: drops contacts whose domain sits on the client's DNC table, and strips the
// underscore-prefixed carriers (_stats, _empty) so the upsert's auto-map never meets a key
// the table does not have. Build Run Log counts the DNC drop as (rows in) minus (rows out).
// Zero survivors still emit one {_empty} placeholder so the Any After DNC? gate reaches the close.
const dnc=new Set();
try{
  const r=$('Get DNC Domains').first().json||{};
  for(const rec of (r.records||[])){ const f=rec.fields||{}; const d=String(f.Domain||f.domain||'').toLowerCase().trim(); if(d) dnc.add(d); }
}catch(e){}
const out=[];
for(const i of $('Clean Fields').all()){
  const j=i.json||{};
  if(j._empty) continue;
  const d=String(j['Domain']||'').toLowerCase().trim();
  if(dnc.size&&d&&dnc.has(d)) continue;
  const row={};
  for(const k of Object.keys(j)){ if(!k.startsWith('_')) row[k]=j[k]; }
  out.push({ json: row });
}
if(!out.length) return [{ json: { _empty:true } }];
return out;

// Head guard tripped: the payload is missing something required. One error, nothing paid.
// 'Failed' is the Error Logger's word for a crash; a guard trip is Succeeded with errors.
const cfg=$('Parse Config').first().json||{};
const missing=(cfg.missing||[]).join(', ')||'unknown';
const row={
 'Automation':'Handle Intent Signal',
 'Status':'Succeeded with errors',
 'Run at': $now.toISO(),
 'Records In': 0,
 'Records Out': 0,
 'Errors': 1,
 'Target': cfg.table||'(no table)',
 'Trigger':'event',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Description': '**Head guard tripped before any paid call, 1 error**\n\n**Missing/invalid params:** '+missing+'\n\n**Required on the Apify webhook payload:** client, table, campaign (URL), resource (carries the dataset id). Fix the payload template on the Apify task and rerun.'
};
if(cfg.client) row['Client']=[cfg.client];
return [{json:row}];

// Build Run Log: the one row this run writes, per the logging standard. Status is computed
// from failed[] (never a literal), skips are separated from errors, and the Description is
// the whole funnel: what came in, why each drop happened, what every paid call returned.
// Every node reference is guarded: a branch that never ran (empty pick, no leads) reads as 0.
const sd=$getWorkflowStaticData('global'); const rs=sd.runStartedAt||0;
const cfg=$('Parse Config').first().json||{};
let base=''; try{ base=$('Client Vars').first().json.base||''; }catch(e){}
const nf=(x)=>Number(x||0).toLocaleString('en-US');
const failed=[];
const skips=[];

// Funnel in: scrape and qualification.
let fq={ jobs_in:0, qualified:0, drops:{} };
try{ const s=$('Filter & Qualify Jobs').first().json._stats; if(s) fq=s; }catch(e){}
const d=fq.drops||{};
const dropLine=['country '+nf(d.country),'staffing name '+nf(d.staffing_name),'staffing industry '+nf(d.staffing_industry),'body shop '+nf(d.body_shop),'headcount '+nf(d.headcount),'no domain '+nf(d.no_domain),'duplicate '+nf(d.duplicate),'already worked '+nf(d.worked)].join(' · ');

// Providers and the merged contact set.
let bl={ companies:fq.qualified, companies_with_contact:0, contacts:0, contagen:{}, supersoniq:{}, bizdata:{}, failed:[] };
try{ const s=$('Build Intent Leads').first().json._stats; if(s) bl=s; }catch(e){}
let recruiters=[]; try{ recruiters=($('Split Calls').first().json._stats||{}).recruiter_bizdata||[]; }catch(e){}
const called=Math.max(0,(fq.qualified||0)-recruiters.length);
for(const f of (bl.failed||[])) failed.push(f);
const cg=bl.contagen||{}, sq=bl.supersoniq||{}, bz=bl.bizdata||{};

// Clean, DNC, upserts, waterfall.
let cleaned=0; try{ cleaned=$('Clean Fields').all().map(i=>i.json).filter(j=>j&&!j._empty).length; }catch(e){}
let afterDnc=0; try{ afterDnc=$('Apply DNC').all().map(i=>i.json).filter(j=>j&&!j._empty).length; }catch(e){}
const dncDropped=Math.max(0,cleaned-afterDnc);
let upserted=0;
const upsertErr=[];
for(const n of ['Upsert by Email','Upsert by Name+Domain']){
  try{ for(const it of $(n).all()){ const j=it.json||{}; if(j&&j.id) upserted++; else if(j&&j.error) upsertErr.push({ tier:'Upsert', name:n, reason:String((j.error&&(j.error.message||j.error))||'upsert failed').slice(0,120) }); } }catch(e){}
}
for(const f of upsertErr) failed.push(f);
const upsertGap=Math.max(0, afterDnc-upserted-upsertErr.length);
if(upsertGap) failed.push({ tier:'Upsert', name:upsertGap+' row(s)', reason:'no record id came back' });
let wfOk=null, wfErrorPages=0;
try{ const w=$('Run Waterfall').first().json||{}; wfOk=!w.error; wfErrorPages=Number(w.errorPages)||0; }catch(e){}
if(afterDnc&&wfOk===false) failed.push({ tier:'Waterfall', name:'batch call', reason:'errored' });
if(wfErrorPages) failed.push({ tier:'Waterfall', name:wfErrorPages+' page(s)', reason:'error pages' });

// Skips: nothing-to-do is not an error.
if(!fq.qualified) skips.push('Skipped (contacts, no company qualified)');
if(fq.qualified&&!bl.contacts) skips.push('Skipped (enrollment, no contact found at '+nf(fq.qualified)+' companies)');
if(bl.contacts&&!afterDnc) skips.push('Skipped (enrollment, all '+nf(bl.contacts)+' contacts on DNC)');

const errs=failed.length;
const status=errs?'Succeeded with errors':'Succeeded';
const head='**'+nf(upserted)+' upserted from '+nf(bl.contacts)+' contacts at '+nf(bl.companies_with_contact)+' of '+nf(fq.qualified)+' companies, '+errs+' error'+(errs===1?'':'s')+'**';
const lines=[
  head,
  '',
  '**Play table:** '+(cfg.table||'(unknown)')+' in '+(base||'(unknown base)')+' · **Event:** '+(cfg.event_type||''),
  '',
  '**Funnel**',
  '- **Jobs scraped:** '+nf(fq.jobs_in),
  '- **Dropped:** '+dropLine,
  '- **Companies qualified:** '+nf(fq.qualified)+(recruiters.length?' · **recruiter platforms (BizData) dropped:** '+recruiters.length+' ('+recruiters.join(', ')+')':''),
  '- **BizData:** '+nf(bz.called)+' calls · '+nf(bz.matched)+' matched · '+nf(bz.unknown||0)+' unknown domain · '+nf(bz.errors)+' errors',
  '- **ContaGen:** '+nf(cg.called)+' calls · '+nf(cg.matched)+' returned people · '+nf(cg.contacts)+' contacts · '+nf(cg.kept)+' kept · '+nf(cg.errors)+' errors',
  '- **Supersoniq:** '+nf(sq.called)+' calls · '+nf(sq.matched)+' returned people · '+nf(sq.contacts)+' contacts · '+nf(sq.kept)+' net-new kept · '+nf(sq.credits)+' credits · '+nf(sq.errors)+' errors',
  '- **Contacts after dedupe:** '+nf(bl.contacts)+' at '+nf(bl.companies_with_contact)+' companies'+(called?' ('+nf(called-bl.companies_with_contact)+' companies with nobody found at either source)':''),
  '- **Cleaned:** '+nf(cleaned)+' · **after DNC:** '+nf(afterDnc)+(dncDropped?' ('+nf(dncDropped)+' on DNC)':''),
  '- **Upserted to intent table:** '+nf(upserted),
  '',
  '**Waterfall batch fired:** '+(afterDnc?(wfOk?'yes (sweeps all rows not done/verifying)':'no / errored'):'not needed'),
  '',
  '**Enrollment:** handled by the daily Add Leads runs'
];
if(failed.length) lines.push('','**FAILED ('+failed.length+')**\n'+failed.slice(0,8).map(f=>'- '+f.tier+' · '+(f.name||'?')+': '+(f.reason||'')).join('\n')+(failed.length>8?'\n- ...and '+(failed.length-8)+' more':''));
if(skips.length) lines.push('',skips.join('\n'));
const row={
 'Automation':'Handle Intent Signal',
 'Status':status,
 'Run at': $now.toISO(),
 'Records In': bl.contacts||0,
 'Records Out': upserted,
 'Errors': errs,
 'Target': cfg.table||'',
 'Trigger':'event',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': lines.join('\n')
};
if(cfg.client) row['Client']=[cfg.client];
return [{json:row}];

let cv=null; try{ cv=$('Client Vars').first().json; }catch(e){}
if(!cv||!cv.clientSlug) return [];
const cfg=$('Parse Config').first().json||{};
let upserted=0;
try{ upserted+=$('Upsert by Email').all().map(i=>i.json).filter(j=>j&&j.id).length; }catch(e){}
try{ upserted+=$('Upsert by Name+Domain').all().map(i=>i.json).filter(j=>j&&j.id).length; }catch(e){}
return [{ json: {
  recordId: cv.clientRecId||cfg.client||'',
  clientSlug: cv.clientSlug||'',
  base: cv.base||'', table: cfg.table||'', campaign_url: cfg.campaign_url||'', sender: cfg.sender||'webhook',
  upserted: upserted
}}];

// Base guard tripped: the client row has no Clayroots Base ID. One error, nothing paid.
const cfg=$('Parse Config').first().json||{};
const row={
 'Automation':'Handle Intent Signal',
 'Status':'Succeeded with errors',
 'Run at': $now.toISO(),
 'Records In': 0,
 'Records Out': 0,
 'Errors': 1,
 'Target': cfg.table||'(no table)',
 'Trigger':'event',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Description': '**No Clayroots Base ID on the client row, 1 error**\n\n**Client row:** '+(cfg.client||'(unknown)')+'\n\nHead guard tripped after the client row read: without a Clayroots Base ID the intent table cannot be resolved. Fill Clayroots Base ID on the Hub Clients row and rerun.'
};
if(cfg.client) row['Client']=[cfg.client];
return [{json:row}];

// Split Calls: every qualified company becomes one row per decision-maker spec, each row
// carrying the request body for BOTH contact sources. The HTTP nodes downstream read the body
// off the row in front of them ($json.cg / $('Split Calls').item.json.sq), so one node fires
// once per row and never knows how many specs a play runs.
//
// The specs come from Parse Config (payload knobs, defaults there); nothing here is a filter,
// with one exception that has to live after BizData: a company whose top DiscoLike industry
// group is HR / staffing is a recruiting platform posting someone else's job (proven live
// 2026-08-23: Jack & Jill, HUMAN_RESOURCES 0.98, "DevOps Engineer at Phonely"). Those get no
// paid contact call; they are reported on the first row's _stats for the run log.
// Zero rows still emit one {_empty} placeholder so the Any Calls? gate reaches the close.
const cfg=$('Parse Config').first().json;
const companyRows=$('Filter & Qualify Jobs').all().map(i=>i.json).filter(c=>c&&c.domain);
const specs=Array.isArray(cfg.specs)?cfg.specs:[];

const RECRUITER=new Set(['HUMAN_RESOURCES','STAFFING_RECRUITING','STAFFING','RECRUITING']);
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
let bizItems=[]; try{ bizItems=$('DiscoLike BizData').all(); }catch(e){}
const recruiter=[];
const companies=[];
companyRows.forEach((c,i)=>{
  const it=bizItems[i]; const b=it&&it.json?parse(it.json.body):null;
  const g=b&&typeof b==='object'?b.industry_groups:null;
  if(g&&typeof g==='object'){
    const top=Object.entries(g).sort((a,b2)=>b2[1]-a[1])[0];
    if(top&&RECRUITER.has(String(top[0]).toUpperCase())&&Number(top[1])>=0.8){ recruiter.push(c.domain); return; }
  }
  companies.push(c);
});

const out=[];
for(const c of companies){
  for(const s of specs){
    const cg={ domain:[c.domain], has_linkedin:true, max_companies:1, results_by_company:s.limit };
    if(s.cg.seniority.length) cg.seniority=s.cg.seniority;
    if(s.cg.department.length) cg.department=s.cg.department;
    if(s.cg.title&&s.cg.title.length) cg.title=s.cg.title;
    if(s.cg.negate_title&&s.cg.negate_title.length) cg.negate_title=s.cg.negate_title;
    const filters={ has_linkedin:true };
    if(s.sq.seniority.length) filters.seniority=s.sq.seniority;
    if(s.sq.function.length) filters.function=s.sq.function;
    out.push({ json: {
      domain:c.domain, company:c.company, call:s.call, limit:s.limit,
      cg,
      sq:{ companies:[{ domain:c.domain }], filters, tier:'full', per_company_limit:s.limit, confirm:true }
    }});
  }
}
const stats={ recruiter_bizdata:recruiter, calls:out.length };
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;
